class AsyncCustomerDao {                       // C++20 coroutines
public:
  virtual ~AsyncCustomerDao() = default;
  virtual awaitable<std::optional<Customer>> find(long id) = 0;
};

awaitable<std::optional<Customer>> MySqlDao::find(long id) {
  mysql::results result;
  co_await conn_.async_execute(
      "SELECT id, name, version FROM customer WHERE id = ?", {id}, result);
  co_return map_first_row(result);             // no result-set type escapes
}
